/// A value of a font descriptor: `str`, `int`, `float` or a tuple of floats
/// (`FontBBox`).
#[derive(Clone, Copy, Debug, PartialEq)]
pub enum FontMetricValue {
    Str(&'static str),
    Int(i64),
    Float(f64),
    FloatTuple(&'static [f64]),
}

/// One entry of `FONT_METRICS`: `(descriptor, widths)`, both dicts, as
/// `(key, value)` pairs in the order of the dict.
#[derive(Debug)]
pub struct FontMetrics {
    pub descriptor: &'static [(&'static str, FontMetricValue)],
    pub widths: &'static [(&'static str, i64)],
}

